from html import escape
LINKS=[('Book your appointment','Choose your hair service and find a time that suits you.','https://bookings.gettimely.com/thesnippitypip/bb/book'),('A little gift of confidence','Treat someone to a Snippity Pip gift voucher.','https://bookings.gettimely.com/thesnippitypip/bb/purchase?giftVoucherId=402852'),('View your appointment','Find the details of your upcoming visit.','https://bookings.gettimely.com/thesnippitypip/'),('Your personal details','Keep your customer contact information up to date.','https://bookings.gettimely.com/thesnippitypip/details/update')]
def customer_links():
    cards=''.join(f'<a class="customer-card" href="{escape(url,quote=True)}" target="_blank" rel="noopener noreferrer"><span class="eyebrow">0{i+1} / Hair customers</span><h3>{title}</h3><p>{body}</p><span class="text-link">Open in Timely ↗</span></a>' for i,(title,body,url) in enumerate(LINKS))
    return '<section class="section soft" id="customer-links"><div class="wrap"><span class="eyebrow">Your salon, a little closer</span><h2>Everything for<br><em>your next visit.</em></h2><p class="lead">Book a little time for yourself, send a thoughtful gift or manage your appointment.</p><div class="customer-grid">'+cards+'</div><p class="small muted">For hairdressing customers. These links open our Timely booking service in a new tab.</p><a class="text-link" href="https://thesnippitypip.gettimely.com/" target="_blank" rel="noopener noreferrer">Visit our Timely booking page ↗</a></div></section>'
def testimonials(academy=False):
    kind='learner' if academy else 'client'
    title='Stories of learning.<br><em>Confidence for what’s next.</em>' if academy else 'Lovely hair.<br><em>Lovely words.</em>'
    return f'<section class="section testimonials" id="testimonials"><div class="wrap testimonial-layout"><div><span class="eyebrow">{ "Academy testimonials" if academy else "Hairdressing testimonials" }</span><h2>{title}</h2><p class="lead">{ "A space for our learners to share their academy experience." if academy else "A space for our clients to share their time in the salon." }</p></div><div class="testimonial-placeholder"><span class="testimonial-mark" aria-hidden="true">“</span><span class="eyebrow">Your stories, coming soon</span><h3>Kind words belong here.</h3><p>We’re making room for genuine {kind} feedback. Testimonials will appear here once they’re ready to share.</p><span class="testimonial-note">Testimonial area · awaiting approved reviews</span></div></div></section>'
